// Exchange rates on a transaction's date (docs/adr/0016): the ECB's daily euro reference rates,
// which Danmarks Nationalbanken's DKK rates are also derived from. The table is generated by
// scripts/exchange-rates.ts into src/data/exchangeRates.ts.

import { currencyRates, toDKK, type CurrencyRate } from '../data/currencies'
import { dailyRates } from '../data/exchangeRates'

/** Units of each currency per euro, per ECB business day. */
export type DailyRates = {
  /** The currencies, in the order of each day's values */
  codes: readonly string[]
  /** [ISO date, values], oldest first */
  days: readonly (readonly [string, readonly (number | null)[]])[]
}

/** Fixed rates, optionally with daily rates that take precedence on a line's date. */
export type RateSource = readonly CurrencyRate[] | { fixed: readonly CurrencyRate[]; daily: DailyRates }

/** How many days back a rate may come from: covers weekends and the longest holiday closures. */
export const MAX_DAYS_BACK = 7

export type DkkRate = {
  /** DKK per unit; null when there's no rate to use */
  value: number | null
  /** The date of the daily rate used, or null for a fixed rate */
  rateDate: string | null
  /** Why the line didn't get the rate on its date */
  note: string | null
}

const dayMs = 86_400_000
const daysBetween = (a: string, b: string) => Math.round((Date.parse(b) - Date.parse(a)) / dayMs)

/** Index of the last day on or before `date`, or -1. */
function lastOnOrBefore(days: DailyRates['days'], date: string): number {
  let lo = 0
  let hi = days.length - 1
  let found = -1
  while (lo <= hi) {
    const mid = (lo + hi) >> 1
    if (days[mid][0] <= date) { found = mid; lo = mid + 1 } else hi = mid - 1
  }
  return found
}

/** The daily rate for a code on the date or up to MAX_DAYS_BACK before, as DKK per unit. */
export function dailyDkkRate(daily: DailyRates, code: string, date: string): { value: number; rateDate: string } | null {
  const dkk = daily.codes.indexOf('DKK')
  const c = daily.codes.indexOf(code)
  if (dkk === -1 || (c === -1 && code !== 'EUR')) return null
  for (let i = lastOnOrBefore(daily.days, date); i >= 0; i--) {
    const [day, values] = daily.days[i]
    if (daysBetween(day, date) > MAX_DAYS_BACK) return null
    const perEurDkk = values[dkk]
    const perEur = code === 'EUR' ? 1 : values[c]
    if (perEurDkk != null && perEur != null && perEur > 0) return { value: perEurDkk / perEur, rateDate: day }
  }
  return null
}

/**
 * DKK per unit of a currency for a line dated `date`. With daily rates: the rate on the date, or
 * the last one before it within MAX_DAYS_BACK. Without one, a known fixed rate is used and the
 * line says so; an unknown currency has no rate, rather than being taken as DKK.
 */
export function dkkRate(source: RateSource, code: string | null | undefined, date: string): DkkRate {
  const cur = (code || 'DKK').toUpperCase()
  if (cur === 'DKK') return { value: 1, rateDate: null, note: null }
  const fixed = Array.isArray(source) ? (source as readonly CurrencyRate[]) : (source as { fixed: readonly CurrencyRate[] }).fixed
  const known = fixed.some((r) => r.code === cur)
  if (Array.isArray(source)) return { value: known ? toDKK(fixed, cur) : 1, rateDate: null, note: null }
  const daily = dailyDkkRate((source as { daily: DailyRates }).daily, cur, date)
  if (daily) return { ...daily, note: null }
  if (known) return { value: toDKK(fixed, cur), rateDate: null, note: `Ingen dagskurs for ${cur} den ${date} — fast kurs brugt.` }
  return { value: null, rateDate: null, note: `Ingen kurs for ${cur} den ${date}.` }
}

/** What the app converts spend with: the daily rates, falling back to the fixed ones. */
export const appRates: RateSource = { fixed: currencyRates, daily: dailyRates }
